/// The `st25r39xx-spi` decoder node.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct St25r39xxSpi {
    config: Config,
}

impl St25r39xxSpi {
    /// A decoder for `config`.
    pub fn new(config: Config) -> Result<Self, ConfigError> {
        config.validate()?;
        Ok(Self { config })
    }

    /// The configuration.
    pub fn config(&self) -> &Config {
        &self.config
    }

    /// The input of the decoder added as `node`.
    pub fn input(node: NodeId) -> InputRef<SpiEvent> {
        InputRef::of_node(node, 0)
    }

    /// The event output of the decoder added as `node`.
    pub fn events(node: NodeId) -> OutputRef<Event> {
        OutputRef::of_node(node, 0)
    }
}

impl Node for St25r39xxSpi {
    fn spec(&self) -> NodeSpec {
        NodeSpec {
            name: "st25r39xx-spi".into(),
            inputs: vec![InputSpec::new::<SpiEvent>("bus", self.config.requires())],
            outputs: vec![OutputSpec::new::<Event>("events", self.config.props())],
        }
    }

    fn start(self: Box<Self>, mut io: Io) -> NodeFuture {
        let rate = io.time_base().map_or(0, |base| base.rate_hz);
        let state = State::new(self.config, rate);
        Box::pin(run_bus(state, io.input(0), io.output(0)))
    }
}

/// The decoder's state: its configuration, the source's rate and its fields.
struct State {
    config: Config,
    rate: u64,
    open: Option<u64>,
    space: Space,
}

impl State {
    fn new(config: Config, rate: u64) -> Self {
        let open: Option<u64> = None;
        let space: Space = Space::A;
        Self {
            config,
            rate,
            open,
            space,
        }
    }

    fn hold(&self) -> Option<u64> {
        None
    }

    async fn recover(
        &mut self,
        io: &mut BusIo<Event>,
        reason: End,
        r#where: Provenance,
    ) -> Result<(), Cut> {
        if let Some(open) = self.open {
            self.open = None;
            io.out.emit(r#where, Event::End { tx: open, reason }).await;
        }
        Ok(())
    }

    fn direct(&self, opcode: u8) -> Direct {
        if (opcode == 192u8) {
            return Direct::SetDefault;
        }
        if (opcode == 193u8) {
            return Direct::SetDefault;
        }
        if (opcode == 194u8) {
            return Direct::Stop;
        }
        if (opcode == 195u8) {
            return Direct::Stop;
        }
        if (opcode == 196u8) {
            return Direct::TransmitCrc;
        }
        if (opcode == 197u8) {
            return Direct::TransmitNoCrc;
        }
        if (opcode == 198u8) {
            return Direct::Reqa;
        }
        if (opcode == 199u8) {
            return Direct::Wupa;
        }
        if (opcode == 200u8) {
            return Direct::InitialFieldOn;
        }
        if (opcode == 201u8) {
            return Direct::ResponseFieldOn;
        }
        if (opcode == 205u8) {
            return Direct::Sense;
        }
        if (opcode == 206u8) {
            return Direct::Sleep;
        }
        if (opcode == 208u8) {
            return Direct::MaskRx;
        }
        if (opcode == 209u8) {
            return Direct::UnmaskRx;
        }
        if (opcode == 210u8) {
            return Direct::ChangeAm;
        }
        if (opcode == 211u8) {
            return Direct::MeasureAmplitude;
        }
        if (opcode == 213u8) {
            return Direct::ResetRxGain;
        }
        if (opcode == 214u8) {
            return Direct::AdjustRegulators;
        }
        if (opcode == 216u8) {
            return Direct::CalibrateDriver;
        }
        if (opcode == 217u8) {
            return Direct::MeasurePhase;
        }
        if (opcode == 218u8) {
            return Direct::ClearRssi;
        }
        if (opcode == 219u8) {
            return Direct::ClearFifo;
        }
        if (opcode == 220u8) {
            return Direct::Transparent;
        }
        if (opcode == 221u8) {
            return Direct::CalibrateCapacitance;
        }
        if (opcode == 222u8) {
            return Direct::MeasureCapacitance;
        }
        if (opcode == 223u8) {
            return Direct::MeasureSupply;
        }
        if (opcode == 224u8) {
            return Direct::StartGeneralTimer;
        }
        if (opcode == 225u8) {
            return Direct::StartWakeTimer;
        }
        if (opcode == 226u8) {
            return Direct::StartMaskTimer;
        }
        if (opcode == 227u8) {
            return Direct::StartResponseTimer;
        }
        if (opcode == 228u8) {
            return Direct::StartPpon2Timer;
        }
        if (opcode == 232u8) {
            return Direct::StopResponseTimer;
        }
        return Direct::Unknown;
    }

    fn layout(&self, opcode: u8) -> Layout {
        if (opcode >= 192u8) {
            return Layout {
                address: (u16::from(opcode) & 63u16),
                read: false,
                step: 0u8,
                count: Some(0u8),
                dummy: 0u8,
                valid: (self.direct(opcode) != Direct::Unknown),
            };
        }
        if ((opcode == 128u8) || (opcode == 159u8)) {
            return Layout {
                address: 0u16,
                read: (opcode == 159u8),
                step: 0u8,
                count: None,
                dummy: 0u8,
                valid: true,
            };
        }
        return Layout {
            address: (u16::from(opcode) & 63u16),
            read: ((opcode & 64u8) != 0u8),
            step: 1u8,
            count: None,
            dummy: 0u8,
            valid: (opcode < 128u8),
        };
    }

    fn operation(&self, opcode: u8, read: bool) -> Operation {
        if (opcode == 128u8) {
            return Operation::FifoWrite;
        }
        if (opcode == 159u8) {
            return Operation::FifoRead;
        }
        if (opcode >= 192u8) {
            return Operation::DirectCommand;
        }
        if ((opcode & 192u8) == 64u8) {
            return Operation::ReadRegister;
        }
        if (opcode < 64u8) {
            return Operation::WriteRegister;
        }
        return if read {
            Operation::ReadRegister
        } else {
            Operation::WriteRegister
        };
    }

    async fn interpret(
        &mut self,
        io: &mut BusIo<Event>,
        tx: u64,
        address: u16,
        value: u8,
        r#where: Provenance,
    ) -> Result<(), Cut> {
        if (address == 0u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::IoConfiguration1,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 1u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::IoConfiguration2,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 2u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::OperationControl,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 3u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::Mode,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 4u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::BitRate,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 26u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::InterruptMain,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 27u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::InterruptTimerNfc,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 28u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::InterruptErrorWake,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 30u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::FifoStatus1,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 31u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::FifoStatus2,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 63u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::Identity,
                        value: u32::from(value),
                    },
                )
                .await;
        }
        if (address == 2u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::OscillatorEnabled,
                        value: Int::shr(u32::from(value), 7),
                    },
                )
                .await;
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::RxEnabled,
                        value: (Int::shr(u32::from(value), 6) & 1u32),
                    },
                )
                .await;
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::RxChannel,
                        value: (Int::shr(u32::from(value), 5) & 1u32),
                    },
                )
                .await;
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::TxEnabled,
                        value: (Int::shr(u32::from(value), 3) & 1u32),
                    },
                )
                .await;
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::WakeEnabled,
                        value: (Int::shr(u32::from(value), 2) & 1u32),
                    },
                )
                .await;
        }
        if (address == 31u16) {
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::FifoBytesHigh,
                        value: (Int::shr(u32::from(value), 6) & 3u32),
                    },
                )
                .await;
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::FifoOverflow,
                        value: (Int::shr(u32::from(value), 4) & 1u32),
                    },
                )
                .await;
            io.out
                .emit(
                    r#where,
                    Event::Field {
                        tx,
                        address,
                        field: Field::FifoUnderflow,
                        value: (Int::shr(u32::from(value), 5) & 1u32),
                    },
                )
                .await;
        }
        Ok(())
    }

    async fn transaction(
        &mut self,
        io: &mut BusIo<Event>,
        tx: &mut Transaction<'_, SpiEvent>,
    ) -> Result<(), Cut> {
        self.space = Space::A;
        self.open = Some(tx.id());
        io.out
            .emit(io.consumed(), Event::Begin { tx: tx.id() })
            .await;
        let mut offset: u32 = 0u32;
        loop {
            let first: Option<SpiEventItem> = {
                io.sink.hold(self.hold().map(Tick));
                match tx.item_or_end().await? {
                    Read::Item(item) => Some(item),
                    Read::End => None,
                }
            };
            let Some(first_2) = first else {
                break;
            };
            let opcode: u8 = required(first_2.mosi)?;
            if ((opcode == 251u8) || (opcode == 252u8)) {
                self.space = if (opcode == 251u8) {
                    Space::B
                } else {
                    Space::Test
                };
                io.out
                    .emit(
                        io.consumed(),
                        Event::Space {
                            tx: tx.id(),
                            space: self.space,
                        },
                    )
                    .await;
                continue;
            }
            let layout: Layout = self.layout(opcode);
            let command_at: Provenance = io.consumed();
            io.out
                .emit(
                    command_at,
                    Event::Command {
                        tx: tx.id(),
                        opcode,
                        address: layout.address,
                        read: layout.read,
                        status: first_2.miso,
                    },
                )
                .await;
            io.out
                .emit(
                    command_at,
                    Event::Operation {
                        tx: tx.id(),
                        operation: self.operation(opcode, layout.read),
                    },
                )
                .await;
            if (opcode >= 192u8) {
                io.out
                    .emit(
                        command_at,
                        Event::Direct {
                            tx: tx.id(),
                            command: self.direct(opcode),
                        },
                    )
                    .await;
            }
            if (!layout.valid) {
                {
                    io.sink.hold(self.hold().map(Tick));
                    tx.drain().await?
                };
                self.open = None;
                io.out
                    .emit(
                        io.consumed(),
                        Event::End {
                            tx: tx.id(),
                            reason: End::Unsupported,
                        },
                    )
                    .await;
                return Ok(());
            }
            for i in (0u8 as u8)..(layout.dummy as u8) {
                {
                    io.sink.hold(self.hold().map(Tick));
                    tx.item().await?
                };
            }
            let mut address: u16 = layout.address;
            let mut count: u32 = 0u32;
            loop {
                if let Some(count_2) = layout.count {
                    if (count >= u32::from(count_2)) {
                        break;
                    }
                }
                let word: Option<SpiEventItem> = if let Some(count_2) = layout.count {
                    Some({
                        io.sink.hold(self.hold().map(Tick));
                        tx.item().await?
                    })
                } else {
                    {
                        io.sink.hold(self.hold().map(Tick));
                        match tx.item_or_end().await? {
                            Read::Item(item) => Some(item),
                            Read::End => None,
                        }
                    }
                };
                let Some(word_2) = word else {
                    self.open = None;
                    io.out
                        .emit(
                            io.consumed(),
                            Event::End {
                                tx: tx.id(),
                                reason: End::Complete,
                            },
                        )
                        .await;
                    return Ok(());
                };
                let value: u8 = if layout.read {
                    required(word_2.miso)?
                } else {
                    required(word_2.mosi)?
                };
                let r#where: Provenance = io.consumed();
                io.out
                    .emit(
                        r#where,
                        Event::Data {
                            tx: tx.id(),
                            offset,
                            address,
                            value,
                            read: layout.read,
                        },
                    )
                    .await;
                if ((opcode < 128u8) && (address > 63u16)) {
                    {
                        io.sink.hold(self.hold().map(Tick));
                        tx.drain().await?
                    };
                    self.open = None;
                    io.out
                        .emit(
                            io.consumed(),
                            Event::End {
                                tx: tx.id(),
                                reason: End::Unsupported,
                            },
                        )
                        .await;
                    return Ok(());
                }
                if (opcode < 128u8) {
                    io.out
                        .emit(
                            r#where,
                            Event::Register {
                                tx: tx.id(),
                                space: self.space,
                                address,
                                register: register_name(self.space, address),
                                value,
                                read: layout.read,
                            },
                        )
                        .await;
                }
                if ((self.space == Space::A) && (opcode < 128u8)) {
                    self.interpret(io, tx.id(), address, value, r#where).await?;
                }
                count = Int::wadd(count, 1u32);
                offset = Int::wadd(offset, 1u32);
                address = Int::wadd(address, u16::from(layout.step));
            }
        }
        self.open = None;
        io.out
            .emit(
                io.consumed(),
                Event::End {
                    tx: tx.id(),
                    reason: End::Complete,
                },
            )
            .await;
        Ok(())
    }
}

impl BusDecoder for State {
    type Lower = SpiEvent;
    type Framer = Declared<SpiEvent>;
    type Event = Event;

    const PARTIAL: Partial = Partial::Drain;

    fn framer(&self) -> Declared<SpiEvent> {
        Declared::new()
    }

    fn hold(&self) -> Option<u64> {
        State::hold(self)
    }

    async fn transaction(
        &mut self,
        io: &mut BusIo<Event>,
        tx: &mut Transaction<'_, SpiEvent>,
    ) -> Result<(), Cut> {
        State::transaction(self, io, tx).await
    }

    async fn recover(&mut self, io: &mut BusIo<Event>, cut: CutKind, at: Provenance) {
        let reason = match cut {
            CutKind::Incomplete => End::Incomplete,
            CutKind::Truncated => End::Aborted,
            CutKind::Missing => End::Aborted,
            CutKind::Gap => End::Aborted,
            CutKind::End => End::Aborted,
        };
        let _ = State::recover(self, io, reason, at).await;
    }

    async fn on_gap(&mut self, _io: &mut BusIo<Event>, _range: TickRange) {}

    async fn on_end(&mut self, _io: &mut BusIo<Event>, _tick: u64) {}

    async fn on_progress(&mut self, _io: &mut BusIo<Event>, _tick: u64) {}
}
